package dev.zomboidmelee.motion;
import java.lang.ref.WeakReference;
public final class BodyPush {
 private static WeakReference<Object> owner=new WeakReference<>(null);private static long started;
 public static double weight(double seconds){if(seconds<=0||seconds>=1)return 0;double v=seconds<.25?seconds/.25:(1-seconds)/.75;return v*v*(3-2*v);}
 public static void begin(Object player){aim(player);owner=new WeakReference<>(player);started=System.nanoTime();}
 public static void apply(Object model,Object entity){if(entity!=owner.get())return;double w=weight((System.nanoTime()-started)/1e9);if(w<=0)return;blend(Lookup.get(model,"rightArm"),"xRot",-1.42f,w);blend(Lookup.get(model,"rightArm"),"yRot",-.13f,w);blend(Lookup.get(model,"rightArm"),"zRot",.12f,w);blend(Lookup.get(model,"leftArm"),"xRot",-1.28f,w);blend(Lookup.get(model,"leftArm"),"yRot",.13f,w);blend(Lookup.get(model,"leftArm"),"zRot",-.12f,w);Object body=Lookup.get(model,"body");float base=((Number)Lookup.get(body,"xRot")).floatValue();Lookup.set(body,"xRot",base+(float)(.15*w));}
 private static void blend(Object part,String field,float desired,double w){float v=((Number)Lookup.get(part,field)).floatValue();Lookup.set(part,field,v+(desired-v)*(float)w);}
 private static void aim(Object player){try{Class<?> bridge=Class.forName("dev.zomboid.isotacz.Bridge");if(!Boolean.TRUE.equals(Lookup.call(bridge,"active")))return;Object mc=Lookup.call(bridge,"mc"),point=Lookup.call(Class.forName("dev.zomboid.isotacz.CursorTarget"),"aimPoint",mc),eye=Lookup.call(player,"getEyePosition");if(point==null||eye==null)return;double dx=num(point,"x")-num(eye,"x"),dy=num(point,"y")-num(eye,"y"),dz=num(point,"z")-num(eye,"z");if(dx*dx+dy*dy+dz*dz<.04)return;float yaw=(float)(Math.toDegrees(Math.atan2(dz,dx))-90),pitch=(float)-Math.toDegrees(Math.atan2(dy,Math.hypot(dx,dz)));Lookup.call(player,"setYRot",yaw);Lookup.call(player,"setXRot",pitch);Lookup.call(player,"setYHeadRot",yaw);Lookup.call(player,"setYBodyRot",yaw);Object packet=Class.forName("net.minecraft.network.protocol.game.ServerboundMovePlayerPacket$Rot").getConstructor(float.class,float.class,boolean.class).newInstance(yaw,pitch,Boolean.TRUE.equals(Lookup.call(player,"onGround")));Lookup.call(Lookup.get(player,"connection"),"send",packet);
 }catch(ClassNotFoundException e){/* Isometric mod optional. */}catch(ReflectiveOperationException|RuntimeException e){System.getLogger("MeleeBodyPush").log(System.Logger.Level.WARNING,"Cursor aim could not be applied",e);}}
 private static double num(Object o,String f){return ((Number)Lookup.get(o,f)).doubleValue();}
}
